// Focus spells are cast with Focus Points. Refocusing for 10 minutes restores 1; your daily preparations restore them all.
export const FocusPoints = ResourcePools.defineResourcePool('focus-points', {
  name: 'Focus Points',
  description: 'Your focus pool holds 1 Focus Point for each focus spell you know, to a maximum of 3.',
  size: 1,
  refresh: [
    { period: GameTimeUnit.ShortRest, amount: 1 },
    { period: GameTimeUnit.LongRest, amount: RelativeAmount.All },
  ],
})

